theorySlides.codeSnippet:
-- Get all data from the users table
SELECT * FROM users;

-- Get only names from the users table
SELECT name FROM users;

-- Get multiple columns
SELECT name, email FROM users;

-- Select specific columns
SELECT name, price FROM products;

-- Select with a different order
SELECT price, name, category FROM products;

-- Columns can be listed in any order you want

-- Find products with price greater than 50
SELECT name, price FROM products
WHERE price > 50;

-- Find a specific user by name
SELECT * FROM users
WHERE name = 'Alice';

-- Find products in a specific category
SELECT * FROM products
WHERE category = 'Electronics';

-- Find products priced at exactly 29.99
SELECT * FROM products WHERE price = 29.99;

-- Find orders with quantity less than 10
SELECT * FROM orders WHERE quantity < 10;

-- Find users who are NOT admins
SELECT * FROM users WHERE role != 'admin';

-- AND: Both conditions must be true
SELECT * FROM products
WHERE category = 'Electronics' AND price < 500;

-- OR: At least one condition must be true
SELECT * FROM products
WHERE category = 'Books' OR category = 'Music';

-- Combining AND and OR (use parentheses!)
SELECT * FROM products
WHERE (category = 'Electronics' OR category = 'Gadgets')
AND price < 100;

-- IN: Instead of multiple OR conditions
SELECT * FROM products
WHERE category IN ('Electronics', 'Computers', 'Phones');

-- BETWEEN: Range of values (inclusive)
SELECT * FROM products
WHERE price BETWEEN 10 AND 50;

-- NOT: Exclude matches
SELECT * FROM products
WHERE category NOT IN ('Clothing', 'Food');

-- Names starting with 'A'
SELECT * FROM users WHERE name LIKE 'A%';

-- Names ending with 'son'
SELECT * FROM users WHERE name LIKE '%son';

-- Names containing 'ann'
SELECT * FROM users WHERE name LIKE '%ann%';

-- Emails from gmail
SELECT * FROM users WHERE email LIKE '%@gmail.com';

-- Names with exactly 4 characters
SELECT * FROM users WHERE name LIKE '____';

-- Sort by name alphabetically (A to Z)
SELECT * FROM users ORDER BY name;

-- Sort by price, lowest first (ascending)
SELECT * FROM products ORDER BY price ASC;

-- Sort by price, highest first (descending)
SELECT * FROM products ORDER BY price DESC;

-- Sort by multiple columns
SELECT * FROM products
ORDER BY category ASC, price DESC;

-- Get only the first 10 products
SELECT * FROM products LIMIT 10;

-- Get the 5 most expensive products
SELECT * FROM products
ORDER BY price DESC
LIMIT 5;

-- Pagination: Skip first 20, get next 10
SELECT * FROM products
LIMIT 10 OFFSET 20;

-- Alternative syntax: LIMIT offset, count
SELECT * FROM products LIMIT 20, 10;

-- Find rows where email is NULL (missing)
SELECT * FROM users WHERE email IS NULL;

-- Find rows where email exists (is NOT NULL)
SELECT * FROM users WHERE email IS NOT NULL;

-- WRONG: This won't work!
SELECT * FROM users WHERE email = NULL;

-- NULLs sort last in ASC, first in DESC
-- Use NULLS FIRST or NULLS LAST to control
SELECT * FROM users
ORDER BY last_login DESC NULLS LAST;

-- Count total number of products
SELECT COUNT(*) FROM products;

-- Count products in a category
SELECT COUNT(*) FROM products
WHERE category = 'Electronics';

-- Sum of all order amounts
SELECT SUM(amount) FROM orders;

-- Average product price
SELECT AVG(price) FROM products;

-- Count non-NULL emails
SELECT COUNT(email) FROM users;

